typedef struct {
    uint8_t temp;
    uint8_t humi;
    uint16_t light;
} EnvData;

QueueHandle_t envQueue;

void sensorTask(void* arg) {
    EnvData data;
    while (1) {
        // 读取DHT11(重试3次)
        int retry = 0;
        while (dht11Read(&data.temp, &data.humi) != 0 && retry < 3) {
            retry++;
            vTaskDelay(200);
        }
        // 读取光敏
        data.light = readADCAverage(10) / 41;  // 0-100
        // 发送队列
        xQueueSend(envQueue, &data, 10);
        vTaskDelay(2000);  // 2秒
    }
}

// 全局最新数据(用Mutex保护)
SemaphoreHandle_t dataMutex;
EnvData latestData;

void updateData(EnvData* data) {
    xSemaphoreTake(dataMutex, portMAX_DELAY);
    latestData = *data;
    xSemaphoreGive(dataMutex);
}

void getData(EnvData* data) {
    xSemaphoreTake(dataMutex, portMAX_DELAY);
    *data = latestData;
    xSemaphoreGive(dataMutex);
}

// 传感器任务调用
EnvData data;
// ... 读取
updateData(&data);
xQueueSend(envQueue, &data, 10);  // 同时发队列

void displayTask(void* arg) {
    EnvData data;
    uint8_t mode = 0;  // 0:主界面 1:报警
    while (1) {
        if (xQueueReceive(envQueue, &data, 100)) {
            oledClear();
            if (mode == 0) {
                // 主界面
                char buf[20];
                oledShowString(0, 0, "Env Monitor");
                sprintf(buf, "Temp: %d C", data.temp);
                oledShowString(0, 2, buf);
                sprintf(buf, "Humi: %d %%", data.humi);
                oledShowString(0, 4, buf);
                sprintf(buf, "Light: %d %%", data.light);
                oledShowString(0, 6, buf);
            } else {
                // 报警界面
                oledShowString(0, 0, "!!WARNING!!");
                char buf[20];
                sprintf(buf, "Temp: %dC", data.temp);
                oledShowString(0, 3, buf);
            }
            oledRefresh();
        }
        // 检查报警
        if (data.temp > 35) mode = 1;
        else mode = 0;
    }
}

// 上报任务
void reportTask(void* arg) {
    while (1) {
        EnvData data;
        getData(&data);  // Mutex保护读取

        // 方式1：二进制帧
        uint8_t frame[8];
        frame[0] = 0xAA;
        frame[1] = 0x55;
        frame[2] = 0x01;  // 设备ID
        frame[3] = data.temp;
        frame[4] = data.humi;
        frame[5] = data.light & 0xFF;
        frame[6] = frame[2] ^ frame[3] ^ frame[4] ^ frame[5];  // 校验
        frame[7] = 0x0D;
        HAL_UART_Transmit(&huart1, frame, 8, 100);

        // 方式2：JSON格式
        char json[50];
        sprintf(json, "{\"id\":1,\"t\":%d,\"h\":%d,\"l\":%d}\r\n",
                data.temp, data.humi, data.light);
        HAL_UART_Transmit(&huart1, (uint8_t*)json, strlen(json), 100);

        vTaskDelay(5000);  // 5秒
    }
}

// 系统整合
QueueHandle_t envQueue;
SemaphoreHandle_t dataMutex;
EnvData latestData;

void alarmTask(void* arg) {
    EnvData data;
    while (1) {
        getData(&data);
        if (data.temp > 35) {
            HAL_GPIO_TogglePin(GPIOC, GPIO_PIN_13);  // LED闪
            HAL_GPIO_WritePin(GPIOB, GPIO_PIN_12, GPIO_PIN_SET);  // 蜂鸣器
            vTaskDelay(200);
        } else {
            HAL_GPIO_WritePin(GPIOC, GPIO_PIN_13, GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOB, GPIO_PIN_12, GPIO_PIN_RESET);
            vTaskDelay(1000);
        }
    }
}

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_I2C1_Init();
    MX_USART1_UART_Init();
    MX_ADC1_Init();
    oledInit();

    envQueue = xQueueCreate(5, sizeof(EnvData));
    dataMutex = xSemaphoreCreateMutex();

    xTaskCreate(sensorTask, "Sensor", 256, NULL, 3, NULL);
    xTaskCreate(displayTask, "Display", 256, NULL, 2, NULL);
    xTaskCreate(reportTask, "Report", 256, NULL, 1, NULL);
    xTaskCreate(alarmTask, "Alarm", 128, NULL, 2, NULL);
    vTaskStartScheduler();
}
